{
  "apiVersion": 1,
  "type": "component.batch",
  "data": {
    "count": 3,
    "results": [
      {
        "selector": "ChatLayout",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatLayout",
            "subComponentOf": "Chat",
            "displayName": "Chat Layout",
            "description": "Layout shell for full chat interfaces. Messages flow in normal page flow, composer is fixed to the bottom with a frosted glass dock. Set density (compact/balanced/spacious) to control spacing, message max-width, and blur layer sizing. Includes built-in auto-scroll, a \"New messages\" scroll-to-bottom button, and a frosted glass blur layer behind the composer. By default the layout root is the scroll container; pass scrollRef to delegate scrolling to a parent element or the document body. Where the visual viewport shrinks for the software keyboard, the composer stays on top of the keyboard, and a conversation at its newest message stays there. In Chrome on Android the composer rides Gboard’s slides in step with them. In Safari on iOS (in the browser and as a home-screen app) and in Firefox for Android, it moves above the keyboard once the browser reports it. On a touch screen, in a top-level page, every way into the composer’s text (a tap, the keyboard’s previous and next buttons, Tab, the input’s focus()) focuses it without scrolling the page; under a mouse or inside an iframe the browser’s own focus applies. Where your page sets interactive-widget=resizes-content, Chrome on Android shrinks the page for the keyboard itself and the composer stays above it without moving (see the browser-support guide).",
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Message content: typically ChatMessageList. Flows naturally in the page and scrolls with the container.",
                "required": true
              },
              {
                "name": "composer",
                "type": "ReactNode",
                "description": "Composer element: typically ChatComposer. Fixed to the bottom with a frosted glass dock.",
                "required": true,
                "slotElements": [
                  {
                    "__element": "TextInput",
                    "props": {
                      "label": "Input",
                      "placeholder": "Type here..."
                    }
                  }
                ]
              },
              {
                "name": "emptyState",
                "type": "ReactNode",
                "description": "Content shown when children is empty. Centered vertically in the message area.",
                "slotElements": [
                  {
                    "__element": "EmptyState",
                    "props": {
                      "title": "No items",
                      "description": "Nothing to show."
                    }
                  }
                ]
              },
              {
                "name": "scrollButton",
                "type": "ReactNode | null",
                "description": "Scroll-to-bottom button rendered above the composer. Defaults to ChatLayoutScrollButton with auto-scroll integration. Pass null to hide."
              },
              {
                "name": "scrollRef",
                "type": "React.RefObject<HTMLElement | null>",
                "description": "External scroll container ref. When provided, auto-scroll and scroll-to-bottom target this element instead of the layout root. Use when the chat is embedded in a page where a parent element or the document body scrolls."
              },
              {
                "name": "density",
                "type": "'compact' | 'balanced' | 'spacious'",
                "description": "Visual density: controls dock padding, message-area max-width and inline padding, and the height of the frosted glass blur layer.",
                "default": "'balanced'"
              }
            ],
            "usage": {
              "description": "ChatLayout is the layout shell for full-page chat interfaces. It renders messages in normal page flow and docks the composer to the bottom with a frosted glass blur layer. Set the density prop to control spacing; it defaults to balanced. Use it to wrap ChatMessageList and ChatComposer for a complete chat experience with built-in auto-scroll and a scroll-to-bottom button.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Pass ChatMessageList as children and ChatComposer as the composer prop for a complete chat interface."
                },
                {
                  "guidance": true,
                  "description": "Provide an emptyState so new conversations show a prompt instead of a blank screen."
                },
                {
                  "guidance": true,
                  "description": "Use scrollRef when the chat is embedded in a page where a parent element handles scrolling."
                },
                {
                  "guidance": true,
                  "description": "Give a full-page ChatLayout a container 100dvh tall, not 100vh: where a phone browser's toolbar collapses, 100vh is the viewport with the toolbar hidden, so the composer would start below the screen's edge."
                },
                {
                  "guidance": false,
                  "description": "Don't apply a fixed height on the layout; let it fill its container with flex: 1."
                },
                {
                  "guidance": false,
                  "description": "Don't render multiple ChatLayout instances in the same scroll container; each expects to own its scroll context."
                }
              ],
              "anatomy": [
                {
                  "name": "Message area",
                  "required": true,
                  "description": "Scrollable region for messages. Renders children (typically ChatMessageList) in a flex column that pushes content to the bottom when the list is short."
                },
                {
                  "name": "Frosted glass dock",
                  "required": true,
                  "description": "Sticky or fixed container at the bottom with a backdrop-blur layer. Houses the scroll button and composer. While a software keyboard is up it sits on top of the keyboard, and the message area gets room to scroll above it."
                },
                {
                  "name": "Scroll-to-bottom button",
                  "required": false,
                  "description": "Appears when the user scrolls up or new messages arrive. Defaults to ChatLayoutScrollButton; pass null to hide or a custom element to override."
                },
                {
                  "name": "Composer",
                  "required": true,
                  "description": "The input area for sending messages, typically ChatComposer. Docked at the bottom inside the frosted glass layer. In a top-level page on a touch screen, its wrapper (without the scroll button) is a group with no name. When the keyboard’s Done ends typing, focus rests on that group (it is no tab stop), so the next tap or Tab starts from the composer. It shows the focus ring after keyboard input only. Under a mouse or inside an iframe, the wrapper is a plain container."
                },
                {
                  "name": "Empty state",
                  "required": false,
                  "description": "Centered placeholder shown when no messages exist. Use EmptyState for a consistent look."
                }
              ]
            },
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatLayoutScrollButton",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatLayoutScrollButton",
            "subComponentOf": "Chat",
            "displayName": "Chat Layout Scroll Button",
            "isHiddenFromOverview": true,
            "description": "Floating scroll-to-bottom button that appears when the user scrolls away from the latest messages. It fades in as a compact icon button and expands to show a label when new messages arrive. ChatLayout renders this by default: pass a custom element to the scrollButton prop to override, or null to hide it entirely.",
            "props": [
              {
                "name": "isVisible",
                "type": "boolean",
                "description": "Whether the button is visible. Bind to a scroll-position check so the button only appears when the user has scrolled up.",
                "required": true
              },
              {
                "name": "label",
                "type": "string",
                "description": "Optional label that expands the button (e.g. \"New messages\"). Use to signal unread content below the fold."
              },
              {
                "name": "onClick",
                "type": "() => void",
                "description": "Click handler: typically scrolls to bottom and dismisses the new message indicator.",
                "required": true
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatMessage",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatMessage",
            "subComponentOf": "Chat",
            "displayName": "Chat Message",
            "description": "Sender context wrapper: handles avatar, name, metadata, and alignment based on sender role.",
            "playground": {
              "defaults": {
                "sender": "assistant",
                "children": {
                  "__element": "ChatMessageBubble",
                  "children": "Here is the summary you asked for."
                },
                "avatar": {
                  "__element": "Avatar",
                  "props": {
                    "name": "Astra",
                    "size": "sm"
                  }
                }
              },
              "wrapper": {
                "component": "Stack",
                "props": {
                  "width": 480
                }
              }
            },
            "props": [
              {
                "name": "sender",
                "type": "'user' | 'assistant' | 'system'",
                "description": "Who sent this message: controls alignment and layout.",
                "required": true
              },
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Free-form content: bubbles, asset lists, tool calls, images. Custom (non-bubble) children render flush with the message edge; wrap them in a ghost ChatMessageBubble to align them with the bubble text column.",
                "required": true,
                "slotElements": [
                  {
                    "__element": "ChatMessageBubble",
                    "children": "Message text"
                  }
                ]
              },
              {
                "name": "avatar",
                "type": "ReactNode",
                "description": "Avatar element rendered beside the message. Typically Avatar. `null`, booleans, and empty strings create no slot; any other content that renders nothing collapses its slot.",
                "slotElements": [
                  {
                    "__element": "Avatar",
                    "props": {
                      "name": "User",
                      "size": "sm"
                    }
                  }
                ]
              },
              {
                "name": "name",
                "type": "ReactNode",
                "description": "Sender name rendered above the message body; it labels the message. `null`, booleans, and empty strings create no slot, and any other content that renders nothing collapses its slot; either way the message is labelled by the translated sender fallback. Use when the first child is raw content (not a bubble). If the first child is a bubble, put the name on the bubble's `name` prop instead."
              },
              {
                "name": "metadata",
                "type": "ReactNode",
                "description": "Metadata rendered below the message body. `null`, booleans, and empty strings create no slot; any other content that renders nothing collapses its slot. Use when the last child is raw content (not a bubble). If the last child is a bubble, put metadata on the bubble's `metadata` prop instead.",
                "slotElements": [
                  {
                    "__element": "Text",
                    "props": {
                      "type": "body"
                    },
                    "children": "Metadata"
                  }
                ]
              },
              {
                "name": "density",
                "type": "'compact' | 'balanced' | 'spacious'",
                "description": "Visual density. Inherited from list context if not set.",
                "default": "'balanced'"
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      }
    ]
  },
  "meta": {
    "answeredBy": {
